CREATE TABLE ConnectionProfiles (ConnectionId TEXT NOT NULL PRIMARY KEY, DisplayName TEXT NOT NULL, ProviderId TEXT NOT NULL, SecretReferenceKind TEXT NOT NULL, SecretReferenceLocator TEXT NOT NULL, BusinessSchema TEXT NOT NULL, StagingSchema TEXT NOT NULL, Version INTEGER NOT NULL, HealthState TEXT NOT NULL, AssessmentMode TEXT NULL, AssessmentRole TEXT NULL, DatabaseIdentity TEXT NULL, ProviderVersion TEXT NULL, CapabilitiesJson TEXT NULL, CleanupFailureCode TEXT NULL, CreatedUtc TEXT NOT NULL, UpdatedUtc TEXT NOT NULL, IdempotencyKey TEXT NOT NULL UNIQUE);
CREATE TABLE SchemaScans (ScanId TEXT NOT NULL PRIMARY KEY, ConnectionId TEXT NOT NULL REFERENCES ConnectionProfiles(ConnectionId) ON DELETE CASCADE, IdempotencyKey TEXT NOT NULL, State TEXT NOT NULL, SnapshotId TEXT NULL, SnapshotHash TEXT NULL, FailureCode TEXT NULL, CreatedUtc TEXT NOT NULL, UpdatedUtc TEXT NOT NULL, UNIQUE (ConnectionId, IdempotencyKey));
CREATE TABLE SchemaSnapshots (SnapshotId TEXT NOT NULL PRIMARY KEY, ConnectionId TEXT NOT NULL REFERENCES ConnectionProfiles(ConnectionId) ON DELETE CASCADE, SnapshotHash TEXT NOT NULL, ContentJson TEXT NOT NULL, CreatedUtc TEXT NOT NULL);
